from pathlib import Path
from openpyxl import load_workbook
import re,sys,warnings
warnings.filterwarnings('ignore',category=UserWarning)
root=Path('hanzai_hakusho')
dirs={i:next(p for p in sorted(root.glob(f'{i}*'),reverse=True) if (p/'MANIFEST.tsv').is_file()) for i in range(66,73)}
def wb(i,f):
 return load_workbook(dirs[i]/(f if '/' in f else 'zuhyo/'+f+'.xlsx'),read_only=True,data_only=True)
def dump(i,f,pat):
 try: b=wb(i,f)
 except FileNotFoundError: return
 for s in b:
  print(i,f,s.title,s.max_row,s.max_column)
  for n,row in enumerate(s.values,1):
   line=' '.join(f'{chr(65+k)}:{v}' for k,v in enumerate(row) if v is not None)
   if line and (n<=8 or re.search(pat,line)):print(n,line)
if __name__=='__main__':
 for i in map(int,sys.argv[1].split(',')):dump(i,sys.argv[2],sys.argv[3])
